73:         readSettings(true);
74:         if(ruleId==null || revision<1 || !dueAt.isAfter(now))throw new IllegalArgumentException("J3_PLAN_MUST_BE_FUTURE");
75:         String key="SCHEDULED|"+ruleId+"|"+revision;
76:         var duplicate=byKey(key);
77:         if(duplicate.isPresent()) {
78:             var existing=duplicate.orElseThrow();
79:             if(!existing.date().equals(date) || !existing.dueAt().equals(micros(dueAt)))throw new IllegalStateException("J3_PLAN_IDENTITY_CONFLICT");
80:             return existing;
81:         }
82:         var previous=jdbc.query("select * from j3_order where rule_id=:rule order by rule_revision desc limit 1",
83:                 Map.of("rule",ruleId),(r,n)->read(r));
84:         if(previous.isEmpty()?revision!=1:revision!=previous.getFirst().ruleRevision()+1)
85:             throw new IllegalStateException("J3_PLAN_REVISION_CONFLICT");
86:         if(!previous.isEmpty()) {
87:             var old=previous.getFirst();
88:             if(old.admittedAt()!=null)throw new IllegalStateException("J3_PLAN_ALREADY_ADMITTED");
89:             if(!old.terminal())terminal(old.id(),OrderState.CANCELLED,"PLAN_REVISED",now);
90:         }
91:         Integer count=jdbc.queryForObject("select count(*) from j3_order where trigger_kind='SCHEDULED' and state in ('FUTURE','QUEUED','RUNNING')",Map.of(),Integer.class);
92:         if(count>=MAXIMUM_PLANS)throw new IllegalStateException("J3_PLAN_LIMIT");
93:         UUID id=UUID.randomUUID();
94:         insert(id,key,ruleId,revision,date,Trigger.SCHEDULED,dueAt,now,null,null);
95:         return find(id).orElseThrow();
96:     }
