114:         Integer queued=jdbc.queryForObject("select count(*) from j3_order where state in ('QUEUED','RUNNING')",Map.of(),Integer.class);
115:         if(queued>100)throw new IllegalStateException("J3_MANUAL_QUEUE_FULL");
