1291:     private static void authenticate(DataInputStream input, String expectedToken)
1292:             throws IOException {
1293:         int magic = input.readInt();
1294:         int version = input.readInt();
1295:         String actualToken = input.readUTF();
1296:         byte[] expected = expectedToken.getBytes(StandardCharsets.UTF_8);
1297:         byte[] actual = actualToken.getBytes(StandardCharsets.UTF_8);
1298:         boolean authenticated;
1299:         try {
1300:             authenticated = magic == MAGIC
1301:                     && version == VERSION
1302:                     && actual.length <= 512
1303:                     && MessageDigest.isEqual(expected, actual);
1304:         }
1305:         finally {
1306:             Arrays.fill(expected, (byte) 0);
1307:             Arrays.fill(actual, (byte) 0);
1308:         }
1309:         if (!authenticated) {
1310:             throw new PlaywrightProviderException(
1311:                     PlaywrightProviderFailure.AUTHENTICATION_FAILED);
1312:         }
1313:     }
